        // Fund the contract with 1 ether
        vm.deal(address(missing), 1 ether);
    }

    function test_withdraw_does_not_emit_custom_event() public {
        // Prepare expected FundsTransferred event signature
        bytes32 fundsSig = keccak256("FundsTransferred(address,uint256)");
        bool foundCustomEvent = false;

        // Record logs during withdrawal
        vm.recordLogs();
        vm.prank(owner);
        missing.withdraw();

        // Check all emitted logs
        Vm.Log[] memory logs = vm.getRecordedLogs();
        for (uint i; i < logs.length; i++) {
            // First topic is always event signature
            if (logs[i].topics[0] == fundsSig) {
                foundCustomEvent = true;
            }
        }

        // Verify event was not emitted
        assertFalse(foundCustomEvent, "FundsTransferred event was emitted");
    }
}
